with with_windows as (select *, round(units / sum(units) over (partition by store_id, product_id), 4) as units_share, ntile(10) over (partition by product_id order by units desc, id) as units_bucket, first_value(units) ignore nulls over (partition by product_id order by units, id rows between unbounded preceding and current row) as first_known_units, sum(units) over (partition by store_id, product_id order by sale_date, id rows between unbounded preceding and current row) as running_units from store_sales where revenue >= 4000) select store_id, approx_percentile(units, array(0.25, 0.5, 0.75)) as units_quartiles, count(distinct id) as distinct_ids, round(avg(units), 2) as avg_units from with_windows group by 1 order by avg_units nulls last;
